#轮换类型为T的置换的计数(柯西Cauchy公式)

def num_cycletype(t):
    t=list(t)
    n=add(t)
    return factorial(n)/ prod([factorial(t.count(i))*(i^t.count(i)) for i in (1..n)])


#定义置换群的轮换指数多项式

def cycle_index_polynomial(G):    
    X=[var("x%s"%i) for i in G.domain()]
    G=map(Permutation,G)
    return add([prod([X[i-1]^list(g.cycle_type()).count(i) for i in (1..max(g.cycle_type()))]) for g in G])



#返回教材给定形式的轮换多项式

def getCycleIndex1(SG5):
    P = SG5.cycle_index()
    n=P.degree()
    R=PolynomialRing(QQ, 'x', n)
    mc=P.monomial_coefficients()
    return add([mc[d]*R.monomial(*(d+[0]*(n-len(d)))) for d in mc])

def num_chg_of_polynomail(f):
    coefs=f.coefficients()
    return num_chg(coefs)

def num_realroots(f,a,b):
    nca=list(map(lambda x:sgn(x(a)),strum_seq(f)))
    ncb=list(map(lambda x:sgn(x(b)),strum_seq(f)))
    return num_chg(nca)-num_chg(ncb)

def find_all_roots(f, a, b, eps=0.0000000001):
    roots = []
    intervals_to_check = [(a,b)]
    while intervals_to_check:
        start, end = intervals_to_check.pop()
        try:
            root = find_root(f, start, end)
        except RuntimeError:
            continue
        if root in roots:
            continue
        if abs(f(x=root)) < 1:
            roots.append(root)
        intervals_to_check.extend([(start, root-eps), (root+eps, end)])
    roots.sort()
    return roots

def shortLex(s1, s2):
    """Shortlex less or equal comparator"""
    if len(s1) > len(s2):
        return False
    if len(s1) < len(s2):
        return True
    return s1 <= s2

def quickSort(nums):  # 这种写法的平均空间复杂度为 O(nlogn)
    if len(nums) <= 1:
        return nums
    pivot = nums[0]  # 基准值
    left = [nums[i] for i in range(1, len(nums)) if shortLex(nums[i], pivot)] 
    right = [nums[i] for i in range(1, len(nums)) if not shortLex(nums[i],pivot)]
    return quickSort(left) + [pivot] + quickSort(right)

def Majorization_Comp(p1,p2): #比较两序列的优超序， 若不等长，返回lNon, 若等长不可比返回Non， 若p1大于等于p2返回True， 若p1小于p2返回False
    if len(p1)!=len(p2):
        return "lNon"
    p1=sorted(p1,reverse=True)
    p2=sorted(p2,reverse=True)
    res=[]
    for k in range(len(p1)):
        res.append(add(p1[:k+1])>=add(p2[:k+1]))
    Res=list(Set(res))
    if len(Res)==2:
        return "Non"
    else:
        return Res[0]

