def H_join(self, GL, UL=None, relabel=True):
    if type(GL) == list:
        if self.order() != len(GL):
            print("图H的阶数要与图列表的长度相同")
            return
    if type(GL) == dict:
        gl = [Graph(1)]*self.order()
        for k in GL:
            gl[k] = GL[k]
        GL = gl
    V = self.vertices()
    VL = []
    EL = []
    i = 0
    nUL = []
    for G in GL:
        VL.append([(i, v) for v in G.vertices()])
        for (u, v) in G.edges(labels=False):
            EL.append(((i, u), (i, v)))
        i = i+1

    if UL:
        i = 0
        for U in UL:
            nUL.append([(i, v) for v in U])
            i = i+1
    else:
        nUL = VL
    for (u, v) in self.edges(labels=False):
        EL = EL+list(map(tuple, cartesian_product([nUL[u], nUL[v]])))
    G = Graph(0)
    G.add_vertices(flatten(VL, max_level=1))
    G.add_edges(EL)
    if relabel:
        G.relabel()
    return G

