    生成一个随机的n阶连通的k圈图。
    """
    if not 0 <= k <= binomial(n-1, 2):
        raise ValueError('参数k超出合理范围！')
    H = graphs.RandomTree(n)
    cE = list(H.complement().edges())
    return H.Add_Edges([cE.pop(randint(0, len(cE)-1)) for _ in range(k)])

