def hermitian_adjacency_matrix(H):
    n = H.order()
    sparse = True
    if n <= 256 or H.density() > 0.05:
        sparse = False
    I = CC(sqrt(-1))
    D = {}
    for i, j, k in H.edge_iterator():
        D[i, j] = I
        if (j, i) in D:
            D[i, j] = 1
            D[j, i] = 1
        else:
            D[j, i] = -I
    return matrix(CC, n, n, D, sparse=sparse)

def Weighted_Adjancency_Matrix(H,f):
