def Rotate_Edges(G, e):
    u, v = e[:2]
    E = G.edges()
    if Set(G[u]).intersection(Set(G[v])) != Set():
        return None
    else:
        E1 = [e for e in E if v in e and e[0] != u]
        E2 = []
        for e in E1:
            e = list(e)
            for i in range(2):
                if e[i] == v:
                    e[i] = u
                    E2.append(e)
        return G.Delete_Edges(E1).Add_Edges(E2)

