def align_HV(Q, H=[], V=[]):
    G = copy(Q)
    pos = G.Pos()
    for sV in H:
        Pos = [pos[v] for v in sV]
        local_center = mean(Pos)
        for v in sV:
            pos[v][1] = local_center[1]
    for sV in V:
        Pos = [pos[v] for v in sV]
        local_center = mean(Pos)
        for v in sV:
            pos[v][0] = local_center[0]
    return G

