        for i in self.Vertices:
            tex += r'''
\coordinate (v{0}) at {1};'''.format(i, pos[i])

        for s, i in colored_sets:
            current_color = colors[i % len(colors)]
            if len(s) == 2:
                s = list(s)
                tex += r"""
