        otV = Set(range(n))-Set(K+V)
        L.update(dict(zip(lK, lV)+zip(otV, otV)))
        rebdict = L
    if L == None:
        rebdict = {v: i for i, v in enumerate(
            sorted(self.Vertices, key=str))}
    return HyperG([edge([rebdict[v] for v in e]) for e in self.Edges])

