def adjacency_tensor(G):
    order = G.uniform()
    dims = G.order()
    if G.order() < max(G.vertices())+1:
        raise TypeError("vertex number error!")
    HE = G.Edges
    Ts = HM(tuple([dims]*order))
    for i in HE:
        for el in Permutations(i):
            Ts[list(el)] = 1
    return (1/factorial(order-1))*Ts

