def add_path(H, v, s, rank=0):
    order = H.order()
    size = H.size()
    r = max(H.rank, rank)
    if type(v) != list:
        v = [v]
    if s == 0:
        return H
    e = edge(v+[order, .., order+r-len(v)-1])
    e.index = size
    E = [e]
    for i in range(s-1):
        e = edge([E[-1][-1], .., E[-1][-1]+r-1])
        e.index = size+i+1
        E.append(e)
    return H.add_edges(E)

def add_paths(H, D, rank=0, copy=True):
    if not isinstance(D, dict):
        D = dict(D)
    for j in D:
        if not isinstance(D[j], list):
            D[j] = [D[j]]
        for i in D[j]:
            H = H.add_path(j, i, rank=rank)
    return H

